  value: 42,
  writable: true,
  configurable: true
};

var fnset = function() {};
var fnget = function() {};

var acDesc = {
  get: fnget,
  set: fnset,
  enumerable: true,
  configurable: false
};

testWithTypedArrayConstructors(function(TA) {
  keys.forEach(function(key) {
